#!/usr/bin/env bash
set -eo pipefail
source /data1/home/sunyiq/miniconda3/etc/profile.d/conda.sh
conda activate nh_final
set -u
export PYTHONDONTWRITEBYTECODE=1
cd /data1/home/sunyiq/zhenjiang_complete_comparison_fixed200_20261019_003/sqrt_gru_recovery
python -B - <<'INDEPENDENT_REPAIR'
PACKED=''
import base64,datetime,fcntl,hashlib,json,os,re,subprocess,sys,traceback,zlib
from pathlib import Path
payload={key:base64.b64decode(value) for key,value in json.loads(zlib.decompress(base64.b64decode(PACKED))).items()}
plan=json.loads(payload['plan.json']);root=Path(plan['canonical_root']);case=plan['case'];repair=Path(plan['repair_directory']);slurm=Path('/usr/local/globle/softs/slurm/19.05.4.1/bin')
result={'schema':'003-independent-projection-repair-result-v1','case':case,'previous_job':plan['original_job'],'validation_job':plan['validation']['job_id'],'job_id':None,'status':'initializing','errors':[],'production_sources_mutation_started':False,'installed_files':[],'actual_training_recovered':False,'old_rejected_helper_executed':False,'automatic_retry_allowed':False}
created=False
def sha(path):
 h=hashlib.sha256()
 with Path(path).open('rb') as f:
  for block in iter(lambda:f.read(1024*1024),b''):h.update(block)
 return h.hexdigest()
def json_new(path,value):
 raw=(json.dumps(value,sort_keys=True,indent=2,allow_nan=False)+'\n').encode();write_new(path,raw)
def write_new(path,raw):
 path.parent.mkdir(parents=True,exist_ok=True)
 with path.open('xb') as f:f.write(raw)
def query(arguments):
 p=subprocess.run(list(map(str,arguments)),capture_output=True,text=True,timeout=60)
 return {'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
def identity():
 files=sorted([*root.joinpath('src').glob('*.py'),*root.joinpath('scripts').glob('*.py'),*root.joinpath('vendor/pytides').glob('*.py')])
 d={p.relative_to(root).as_posix():sha(p) for p in files}
 return hashlib.sha256(json.dumps(d,sort_keys=True,separators=(',',':'),allow_nan=False).encode()).hexdigest()
def assert_empty_queue():
 value=query([slurm/'squeue','-h','-u','sunyiq','-o','%i|%j|%T|%Z|%o'])
 assert value['returncode']==0 and not any(str(root) in line or case in line for line in value['stdout'].splitlines())
 return value
try:
 queue=assert_empty_queue();result['queue_before']=queue
 accounting=query([slurm/'sacct','-n','-X','-j',plan['original_job']+','+plan['validation']['job_id'],'--format=JobID,State,ExitCode,Start,End,NodeList','-P'])
 rows={r[0]:r for r in (line.split('|') for line in accounting['stdout'].splitlines())}
 assert accounting['returncode']==0 and rows[plan['original_job']][1:3]==['FAILED','1:0'] and rows[plan['validation']['job_id']][1:3]==['COMPLETED','0:0']
 result['accounting_before']=accounting
 with (root/'records'/case/'writer.lock').open('rb') as writer:
  fcntl.flock(writer,fcntl.LOCK_EX|fcntl.LOCK_NB);result['exclusive_writer_lock']=True
  assert identity()==plan['original_code_hash']
  assert all(sha(root/name)==expected for name,expected in plan['canonical_metadata_hashes'].items())
  assert all(sha(x['path'])==x['sha256'] for x in plan['source_files'].values())
  for item in plan['complete_checkpoints']:
   assert sha(item['source'])==item['sha256'] and sha(item['preserved_copy'])==item['sha256'],item['member']
  val=plan['validation']
  for k in ('report','status','attempt','plan'):assert sha(val[k+'_path'])==val[k+'_sha256']
  report=json.loads(Path(val['report_path']).read_bytes());status=json.loads(Path(val['status_path']).read_bytes());attempt=json.loads(Path(val['attempt_path']).read_bytes())
  flags=['canonical_writer_lock_exclusively_held','canonical_metadata_unchanged','source_files_unchanged','original_forward_loss_and_nine_gradients_match','original_projection_inputs_and_adjoints_match','exact_contractions_and_rounding_match_original_trace','adjacent_unscaled_and_clipped_gradients_match','clipping_matches_independent_reference','full_model_and_Adam_match_independent_reference']
  assert report==status and not report['errors'] and report['status']=='original_failing_batch_candidate_validation_pass'
  assert str(report['job_id'])==str(attempt['job_id'])==val['job_id'] and report['plan_sha256']==attempt['plan_sha256']==val['plan_sha256']
  assert all(report.get(k) is True for k in flags) and report['device_identity']['name']=='NVIDIA A40'
  assert (report['candidate_optimizer_steps'],report['reference_optimizer_steps'],report['canonical_optimizer_steps'],report['loss_backward_calls'])==(1,1,0,32)
  assert report['loaded_Adam_steps']==[21718]*9 and report['updated_Adam_steps']==[21719]*9
  for name,key in [('ADMISSION.json','admission_sha256'),('USER_AUTHORIZATION.json','user_authorization_sha256'),('run.slurm','batch_sha256'),('new_runner.py','runner_sha256')]:assert hashlib.sha256(payload[name]).hexdigest()==plan[key]
  numerical={'src/gradient_recovery.py','src/projection_gradient_repair.py'};new_sources={}
  for rel,change in plan['source_changes'].items():
   original=root/rel;before=change['before']
   assert (sha(original)==before) if before is not None else not original.exists()
   raw=(Path(plan['validated_candidate_directory'])/rel).read_bytes() if rel in numerical else payload['source/'+rel]
   assert hashlib.sha256(raw).hexdigest()==change['after'];new_sources[rel]=raw
  assert not (root/plan['runner_path']).exists()
  repair.mkdir(parents=True,exist_ok=False);created=True
  json_new(repair/'INDEPENDENT_DEPLOYMENT_ATTEMPT.json',{'plan':plan,'at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'automatic_retry_allowed':False})
  for rel,change in plan['source_changes'].items():
   if change['before'] is not None:write_new(repair/'original_sources'/rel,(root/rel).read_bytes())
  for name in ('plan.json','ADMISSION.json','USER_AUTHORIZATION.json','run.slurm'):write_new(repair/name,payload[name])
  result['production_sources_mutation_started']=True
  for rel,raw in list(new_sources.items())+[(plan['runner_path'],payload['new_runner.py'])]:
   dest=root/rel;temp=dest.with_name(dest.name+'.independent_repair_staged');assert not temp.exists();write_new(temp,raw);os.replace(temp,dest);result['installed_files'].append(rel)
  assert identity()==plan['repair_code_hash'];result['production_sources_installed']=True
  sys.path.insert(0,str(root))
  from src.continuation import load_continuation,verify_migration_receipt
  from src.repair_admission import load_admission,require_approved_failure
  admission=load_admission(root);assert admission['case']==case and len(admission['members'])==12
  for exp_id,expected in admission['members'].items():
   run=root/'runs'/exp_id;require_approved_failure(run)
   state,config,loaded,config_raw,raw=load_continuation(run,200,'cpu');verify_migration_receipt(run,config_raw,loaded['checkpoint_sha256'])
   assert loaded['checkpoint_sha256']==expected['checkpoint_sha256'] and loaded['completed_epochs']==expected['completed_epochs'];del state,config,loaded,config_raw,raw
  jobs_path=root/'records/scheduler_jobs.json';jobs=json.loads(jobs_path.read_bytes());assert str(jobs[case])==plan['original_job']
  result['queue_before_submit']=assert_empty_queue()
  json_new(repair/'INDEPENDENT_SUBMISSION_ATTEMPT.json',{'previous_job':plan['original_job'],'admission_sha256':sha(repair/'ADMISSION.json'),'batch_sha256':sha(repair/'run.slurm'),'automatic_retry_allowed':False})
  submitted=query([slurm/'xbatch',repair/'run.slurm']);result['scheduler_response']=submitted;json_new(repair/'INDEPENDENT_SUBMISSION_RESPONSE.json',submitted)
  assert submitted['returncode']==0,'scheduler submission result uncertain; do not retry'
  match=re.fullmatch(r'Submitted batch job ([0-9]+)\s*',submitted['stdout']);assert match,'scheduler response unrecognized; do not retry'
  job=match.group(1);jobs[case]=job;temporary=jobs_path.with_name(jobs_path.name+'.independent_repair.tmp');write_new(temporary,(json.dumps(jobs,sort_keys=True,indent=2)+'\n').encode());os.replace(temporary,jobs_path)
  binding={'schema':'003-projection-repair-job-binding-v1','case':case,'job_id':job,'previous_job':plan['original_job'],'initial':True,'admission_sha256':sha(repair/'ADMISSION.json'),'actual_code_hash':plan['repair_code_hash'],'source_code_hash':plan['original_code_hash']}
  json_new(repair/'job_bindings'/(job+'.json'),binding);json_new(repair/'INDEPENDENT_SUBMISSION_CONFIRMED.json',binding)
  result.update(status='validated_independent_repair_submitted_once',job_id=job,submission=binding)
except Exception as error:
 result['status']='independent_repair_not_confirmed_preserve_and_stop'
 result['errors'].append({'type':type(error).__name__,'message':str(error),'traceback':traceback.format_exc()})
finally:
 if created:json_new(repair/'INDEPENDENT_DEPLOYMENT_RESPONSE.json',result)
 print('GRU_PROJECTION_INDEPENDENT_RECOVERY_JSON '+json.dumps(result,sort_keys=True),flush=True)

INDEPENDENT_REPAIR
#!/usr/bin/env bash
set -eo pipefail
python3 - <<'READ_FIXED200_003'
"""Read fixed-200 allocation and committed-epoch evidence without loading tensors.

Example on HPC: python -B read_status.py
Reads the two activated cases, checkpoint heads/events and small record files.
Prints a status snapshot only; no scheduler submission or source writes.
"""
import datetime
import hashlib
import json
from pathlib import Path
import subprocess

ROOT = Path('/data1/home/sunyiq/zhenjiang_complete_comparison_fixed200_20261019_003')
SLURM = Path('/usr/local/globle/softs/slurm/19.05.4.1/bin')
CASES = {'legacy_lstm__historical_capacity': 'base',
         'explicit_gru__historical_capacity': 'sqrt_gru_recovery'}


def read(path):
    return json.loads(path.read_bytes())


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def query(command):
    result = subprocess.run(list(map(str, command)), capture_output=True, text=True, timeout=45)
    return {'command': list(map(str, command)), 'returncode': result.returncode,
            'stdout': result.stdout, 'stderr': result.stderr}


def final_stage_metadata(runtime, record, case, row):
    """Read bounded final-stage records and committed heads; never load tensors."""
    result = {'group_outcomes': {}, 'physical_members': {}, 'aliases': {},
              'checkpoints_loaded': False, 'scientific_files_changed': False}
    for suffix in ('tune_branch_group', 'final_foundation_group', 'all_final_branches_group'):
        path = record / (suffix + '_outcome.json')
        if not path.exists():
            continue
        outcome = read(path)
        seal = outcome['seal']
        result['group_outcomes'][suffix] = {
            'path': str(path), 'sha256': sha(path),
            'seal': {key: seal[key] for key in ('group_id', 'member_ids', 'epochs',
                     'checkpoint_hashes', 'status', 'budget_final', 'evidence_sha256')},
            'members': {name: {key: value.get(key) for key in ('case', 'seed', 'method',
                'type', 'epochs', 'budget_final', 'best_epoch', 'checkpoint_sha256',
                'checkpoint_path', 'learning_rate', 'normalization_hash', 'whitening_hash',
                'initializer_hash', 'device_identity')} for name, value in outcome['members'].items()}}
    path = record / 'aliases_before_final_training.json'
    if path.exists():
        aliases = read(path)
        result['alias_record_sha256'] = sha(path)
        result['effective_configs_sha256_before_aliases'] = aliases['effective_configs_sha256']
        result['aliases'] = {name: target for name, target in aliases['aliases'].items()
                             if name.startswith(case + '__')}
    path = record / 'all_final_branches_group_configs.json'
    if not path.exists():
        return result
    configs = read(path)
    result['physical_configs_sha256'] = sha(path)
    for name, config in configs.items():
        assert name.startswith(case + '__') and name not in result['aliases']
        run = config['registration']
        effective = config['effective_config']
        folder = runtime / 'runs' / name
        item = {'method': run['method'], 'type': run['type'], 'seed': run['seed'],
                'learning_rate': effective['learning_rate'],
                'parent_run_id': effective['parent_run_id'], 'parent_hash': effective['parent_hash'],
                'folder_exists': folder.exists(), 'continuation_file_exists': (folder / 'continuation.pt').is_file()}
        config_path = folder / 'config.json'
        if config_path.exists():
            item['config_sha256'] = sha(config_path)
            item['frozen_config_matches'] = read(config_path) == config
        head_path = folder / 'checkpoint_head.json'
        if head_path.exists():
            head = read(head_path)
            assert 0 <= head['completed_epochs'] <= 200
            item['head'] = head
            event_path = folder / 'checkpoint_events' / (head['checkpoint_sha256'][:16] + '.json')
            if head['completed_epochs'] > 0 and event_path.exists():
                event = read(event_path)
                assert event['completed_epochs'] == head['completed_epochs']
                assert event['checkpoint_sha256'] == head['checkpoint_sha256']
                assert event['previous_epochs'] == head['completed_epochs'] - 1
                item['latest_complete_epoch_event'] = event
            anchor_path = folder / 'continuation_anchor.json'
            if anchor_path.exists():
                item['anchor_sha256'] = sha(anchor_path)
                item['anchor'] = read(anchor_path)
                item['head_anchor_matches'] = head.get('anchor_sha256') == item['anchor_sha256']
        step_path = folder / 'first_optimizer_step.json'
        if step_path.exists():
            step = read(step_path)
            item['first_optimizer_step'] = {key: step.get(key) for key in
                ('status', 'epoch', 'training_batch_size', 'method', 'device_identity')}
        failure_path = folder / 'failure.json'
        if failure_path.exists():
            row['failure_records'][name] = read(failure_path)
        result['physical_members'][name] = item
    result['physical_member_count'] = len(configs)
    result['logical_member_count'] = len(configs) + len(result['aliases'])
    result['complete200_physical_members'] = sum(
        value.get('head', {}).get('completed_epochs') == 200 for value in result['physical_members'].values())
    result['complete_member_epochs'] = sum(
        value.get('head', {}).get('completed_epochs', 0) for value in result['physical_members'].values())
    result['all_alias_targets_are_physical'] = all(target in configs for target in result['aliases'].values())
    return result


report = {'schema': 'fixed200-activation-status-v1', 'root': str(ROOT),
          'checked_at_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
          'checkpoints_loaded': False, 'evaluation_values_read': False, 'cases': {}, 'errors': []}
report['queue'] = query([SLURM / 'squeue', '-h', '-u', 'sunyiq', '-o', '%i|%j|%T|%Z|%e|%l|%N|%R'])
for case, variant in CASES.items():
    runtime = ROOT / variant
    record = runtime / 'records' / case
    try:
        initial = read(record / 'activation_starting_members.json')
        job = str(read(runtime / 'records/scheduler_jobs.json')[case])
        auth = read(runtime / 'records/authorization.json')
        row = {'case': case, 'root': str(runtime), 'job_id': job,
               'authorization_sha256': sha(runtime / 'records/authorization.json'),
               'authorization': auth, 'migration_manifest': read(record / 'migration_manifest.json'),
               'data_preparation_complete': read(runtime / 'records/data_preparation_complete.json'),
               'scheduler_script': (runtime / 'hpc/fixed200_case.slurm').read_text(),
               'device_identity': auth['device_identity'], 'members': {},
               'queue_rows': [line for line in report['queue']['stdout'].splitlines() if line.startswith(job + '|')],
               'failure_records': {}}
        allocation = record / ('runtime_binding_' + job + '.json')
        if allocation.exists():
            row['runtime_binding'] = read(allocation)
            assert row['runtime_binding']['device_identity'] == auth['device_identity']
        for name in ('progress.json', 'training_complete.json', 'selected_rates_2021.json',
                     'scheduler_slice_end_' + job + '.json', 'startup_path_recovery_' + job + '.json',
                     'submission_context_repair.confirmed.json'):
            if (record / name).exists():
                row[name] = read(record / name)
        source_outcome = record / 'tune_foundation_group_outcome.json'
        if source_outcome.exists():
            source = read(source_outcome)
            row['tuning_foundation_source'] = {'seal_epochs': source['seal']['epochs'],
                'members': {name: {'epochs': value['epochs'], 'best_epoch': value['best_epoch'],
                           'checkpoint_sha256': value['checkpoint_sha256']}
                            for name, value in source['members'].items()}}
            assert row['tuning_foundation_source']['seal_epochs'] == 400
        for member, start in initial.items():
            folder = runtime / 'runs' / member
            head = read(folder / 'checkpoint_head.json')
            anchor = read(folder / 'continuation_anchor.json')
            assert anchor['initial_checkpoint_sha256'] == start['checkpoint_sha256']
            assert anchor['initial_epochs'] == start['completed_epochs']
            assert sha(folder / 'config.json') == start['config_sha256']
            assert sha(folder / 'migration_source.json') == start['receipt_sha256']
            n = head['completed_epochs']
            assert start['completed_epochs'] <= n <= 200
            item = {'initial_epochs': start['completed_epochs'], 'completed_epochs': n,
                    'new_complete_epochs': n - start['completed_epochs'],
                    'checkpoint_sha256_from_committed_head': head['checkpoint_sha256'],
                    'initial_identity_and_config_preserved': True}
            if n > start['completed_epochs']:
                event = read(folder / 'checkpoint_events' / (head['checkpoint_sha256'][:16] + '.json'))
                assert event['checkpoint_sha256'] == head['checkpoint_sha256']
                assert event['completed_epochs'] == n and event['previous_epochs'] == n - 1
                assert event['anchor_sha256'] == head['anchor_sha256'] == sha(folder / 'continuation_anchor.json')
                item['new_epoch_event'] = event
            if (folder / 'failure.json').exists():
                row['failure_records'][member] = read(folder / 'failure.json')
            row['members'][member] = item
        row['new_complete_member_epochs'] = sum(v['new_complete_epochs'] for v in row['members'].values())
        row['members_with_new_complete_epoch'] = sum(v['new_complete_epochs'] > 0 for v in row['members'].values())
        row['tune_branch_200_complete_members'] = sum(v['completed_epochs'] == 200 for v in row['members'].values())
        row['actual_training_progress_confirmed'] = bool(row.get('runtime_binding') and row['new_complete_member_epochs'] > 0)
        try:
            row['final_stage'] = final_stage_metadata(runtime, record, case, row)
        except Exception as error:
            row['final_stage_metadata_error'] = {'type': type(error).__name__, 'message': str(error)}
        row['logs'] = []
        for path in (runtime / 'logs').glob('*_' + job + '.out'):
            with path.open('rb') as handle:
                handle.seek(max(0, path.stat().st_size - 7000))
                row['logs'].append({'path': str(path), 'tail': handle.read().decode('utf-8', errors='replace')})
        report['cases'][case] = row
    except Exception as error:
        report['errors'].append({'case': case, 'type': type(error).__name__, 'message': str(error)})
jobs = [v['job_id'] for v in report['cases'].values()]
if jobs:
    report['accounting'] = query([SLURM / 'sacct', '-n', '-X', '-j', ','.join(jobs),
                                  '--format=JobID,State,ExitCode,Start,End,NodeList', '-P'])
report['summary'] = {'cases': len(report['cases']),
    'cases_with_new_complete_epoch': sum(v['actual_training_progress_confirmed'] for v in report['cases'].values()),
    'new_complete_member_epochs': sum(v['new_complete_member_epochs'] for v in report['cases'].values()),
    'members_with_new_complete_epoch': sum(v['members_with_new_complete_epoch'] for v in report['cases'].values()),
    'tune_branch_200_complete_members': sum(v['tune_branch_200_complete_members'] for v in report['cases'].values()),
    'failure_files': sum(len(v['failure_records']) for v in report['cases'].values())}
print(json.dumps(report, sort_keys=True), flush=True)

READ_FIXED200_003
